const ready=new Promise((resolve,reject)=>{const q=indexedDB.open('bottlecapture-v1',1);q.onupgradeneeded=()=>{const d=q.result;d.createObjectStore('runs',{keyPath:'id'});d.createObjectStore('photos',{keyPath:'id'});d.createObjectStore('settings',{keyPath:'id'});};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});
export async function all(store){const d=await ready;return new Promise((res,rej)=>{const q=d.transaction(store).objectStore(store).getAll();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
export async function get(store,id){const d=await ready;return new Promise((res,rej)=>{const q=d.transaction(store).objectStore(store).get(id);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
export async function put(store,obj){const d=await ready;return new Promise((res,rej)=>{const t=d.transaction(store,'readwrite');t.objectStore(store).put(obj);t.oncomplete=()=>res(obj);t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error||Error('Storage write cancelled.'));});}
export async function addPhoto(obj){const d=await ready;return new Promise((res,rej)=>{const t=d.transaction('photos','readwrite');t.objectStore('photos').add(obj);t.oncomplete=()=>res(obj);t.onerror=()=>rej(Error('This shot already exists, or storage is full. Your photo was not overwritten.'));});}
export async function setting(id,value){if(value===undefined)return (await get('settings',id))?.value;await put('settings',{id,value});return value;}
